return ['domain'=>NULL,'plural-forms'=>'nplurals=4; plural=(n == 1 || n == 11) ? 0 : ((n == 2 || n == 12) ? 1 : ((n >= 3 && n <= 10 || n >= 13 && n <= 19) ? 2 : 3));','language'=>'gd','project-id-version'=>'Babilim 1.0.0','pot-creation-date'=>'2026-10-31T05:53:15+00:00','po-revision-date'=>'2026-10-31T05:53:15+00:00','x-generator'=>'Babilim','messages'=>['Babilim'=>'Babilim','Fills in missing translations for the plugins and themes already installed on your site.'=>'Lìonaidh e na h-eadar-theangachaidhean a tha a dhìth airson na plugain agus na cuspairean a tha stàlaichte air an làrach agad mar-thà.','Translations'=>'Eadar-theangachaidhean','Babilim Settings'=>'Roghainnean Babilim','Settings'=>'Roghainnean','You are not allowed to do this.'=>'Chan eil cead agad seo a dhèanamh.','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'Tagh nas lugha de cho-phàirtean: %1$d gnìomhachd air a\' char as motha gach ruith (thagh thu %2$d).','That component is not installed on this site, so a translation cannot be requested for it.'=>'Chan eil am pàirt sin air a stàladh air an làrach seo, agus mar sin chan urrainn eadar-theangachadh iarraidh air a shon.','Already installed.'=>'Stàlaichte mar-thà.','Downloaded and installed.'=>'Chaidh a luchdadh a-nuas agus a stàladh.','Babilim has not been enabled for this site yet.'=>'Chan eil Babilim air a chur an comas airson na làraich seo fhathast.','No build is available to download for this locale.'=>'Chan eil togail ri fhaighinn airson a luchdadh a-nuas airson an sgeama ionadail seo.','Rolled back to the previous build.'=>'Chaidh a thilleadh dhan build roimhe.','Rolled back and reported.'=>'Chaidh a thilleadh agus aithris.','Rolled back, but the report could not be sent: %s'=>'Chaidh a thilleadh, ach cha b\' urrainnear an aithisg a chur: %s','Removed.'=>'Chaidh a thoirt air falbh.','Translation requested.'=>'Chaidh eadar-theangachadh iarraidh.','This component was already uploaded. Babilim is checking it now.'=>'Chaidh am pàirt seo a luchdadh suas mar-thà. Tha Babilim ga sgrùdadh an-dràsta.','Upload cancelled.'=>'Chaidh an luchdadh suas a chur dheth.','Upload complete — translation requested.'=>'Luchdadh suas deiseil — chaidh eadar-theangachadh iarraidh.','This component does not declare a version number, so a translation cannot be requested for it.'=>'Chan eil am pàirt seo a’ cur an cèill àireamh tionndaidh, agus mar sin chan urrainn eadar-theangachadh iarraidh air a shon.','This component\'s version number is longer than %d characters, which Babilim cannot handle, so a translation cannot be requested for it.'=>'Tha àireamh tionndaidh a’ phàirt seo nas fhaide na %d caractar, rud nach urrainn do Babilim làimhseachadh, agus mar sin chan urrainn eadar-theangachadh iarraidh air a shon.','A translation cannot be requested for that locale on this site right now.'=>'Chan urrainnear eadar-theangachadh iarraidh airson an locale sin air an làrach seo an-dràsta.','Thank you. Your report was sent.'=>'Tapadh leibh. Chaidh an aithisg agad a chur.','This report does not name a valid plugin or theme and locale.'=>'Chan eil an aithisg seo ag ainmeachadh plugan no cuspair agus locale dligheach.','Please choose a category for this report.'=>'Tagh roinn-seòrsa airson na h-aithisge seo.','This report is missing a valid build to report against.'=>'Chan eil build dligheach aig an aithisg seo airson aithris a dhèanamh air.','This build is not one this site currently knows about for this component/locale.'=>'Chan e build a tha an làrach seo a’ aithneachadh an-dràsta airson a’ phàirt/ionadail seo a th’ ann.','The field "%1$s" is too long: it has %2$d characters and the limit is %3$d. Nothing was sent; please shorten it and try again.'=>'Tha an raon "%1$s" ro fhada: tha %2$d caractar ann agus is e %3$d a\' chrìoch. Cha deach dad a chur; giorraich e agus feuch ris a-rithist.','Original string'=>'An sreang thùsail','String context'=>'Co-theacsa an t-sreang','Current translation'=>'An t-eadar-theangachadh làithreach','Suggested translation'=>'Eadar-theangachadh molta','Note (optional)'=>'Nòta (roghainneil)','Where you saw this (optional)'=>'Càite am faca tu seo (roghainneil)','Babilim sync is temporarily delayed by the service (rate limited); it will try again after %s.'=>'Tha sioncronachadh Babilim air a chuingealachadh rè ùine leis an t-seirbheis (cuingealachadh ìre); feuchaidh e a-rithist às dèidh %s.','That is not a valid WordPress locale code. Nothing was saved.'=>'Chan e còd ionadail WordPress dligheach a tha sin. Cha deach dad a shàbhaladh.','Settings saved.'=>'Chaidh na roghainnean a shàbhaladh.','If this is on, uninstalling also erases this site\'s identity. The paid license attached to this site cannot be restored automatically afterwards; you would have to contact Babilim support at %s to get it back.'=>'Ma tha seo air, sguabaidh dì-stàladh às dearbh-aithne na làraich seo cuideachd. Chan urrainn dhuinn an cead-cleachdaidh pàighte a tha ceangailte ris an làrach seo aiseag gu fèin-obrachail às dèidh sin; dh’fheumadh tu fios a chur gu taic Babilim aig %s gus a faighinn air ais.','Babilim is set to erase this site\'s identity when the plugin is deleted. The paid license attached to this site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in the Babilim settings, and deactivate again. Deactivate anyway?'=>'Tha Babilim air a shuidheachadh gus dearbh-aithne na làraich seo a sguabadh às nuair a thèid am plugan a sguabadh às. Chan urrainnear an cead-cleachdaidh pàighte a tha ceangailte ris an làrach seo aiseag gu fèin-obrachail an uairsin; dh’fheumadh tu fios a chur gu taic Babilim aig %s. Gus an dearbh-aithne a chumail, briog air Sguir dheth, thoir an tic far “Sguab às a h-uile dàta Babilim nuair a thèid a dhì-stàladh” ann an Roghainnean Babilim, agus dì-ghnìomhaich a-rithist. A bheil thu airson a dhì-ghnìomhachadh co-dhiù?','%1$d site on this network is set to erase its Babilim identity when the plugin is deleted. The paid license attached to that site could then not be restored automatically; you would have to contact Babilim support at %2$s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in that site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'Tha %1$d làrach air an lìonra seo air a suidheachadh gus an dearbh-aithne Babilim aice a sguabadh às nuair a thèid am plugan a sguabadh às. Chan urrainnear an cead-cleachdaidh pàighte a tha ceangailte ris an làrach sin aiseag gu fèin-obrachail an uairsin; dh’fheumadh tu fios a chur gu taic Babilim aig %2$s. Gus an dearbh-aithne a chumail, briog air Sguir dheth, thoir an tic far “Sguab às a h-uile dàta Babilim nuair a thèid a dhì-stàladh” ann an Roghainnean Babilim na làraich sin, agus dì-ghnìomhaich a-rithist. A bheil thu airson a dhì-ghnìomhachadh co-dhiù?' . "\0" . 'Tha %1$d làrach air an lìonra seo air an suidheachadh gus an dearbh-aithne Babilim aca a sguabadh às nuair a thèid am plugan a sguabadh às. Chan urrainnear an cead-cleachdaidh pàighte a tha ceangailte ris na làraichean sin aiseag gu fèin-obrachail an uairsin; dh’fheumadh tu fios a chur gu taic Babilim aig %2$s. Gus na dearbh-aithnean a chumail, briog air Sguir dheth, thoir an tic far “Sguab às a h-uile dàta Babilim nuair a thèid a dhì-stàladh” ann an Roghainnean Babilim gach làraich, agus dì-ghnìomhaich a-rithist. A bheil thu airson a dhì-ghnìomhachadh co-dhiù?' . "\0" . 'Tha %1$d làrach air an lìonra seo air an suidheachadh gus an dearbh-aithne Babilim aca a sguabadh às nuair a thèid am plugan a sguabadh às. Chan urrainnear an cead-cleachdaidh pàighte a tha ceangailte ris na làraichean sin aiseag gu fèin-obrachail an uairsin; dh’fheumadh tu fios a chur gu taic Babilim aig %2$s. Gus na dearbh-aithnean a chumail, briog air Sguir dheth, thoir an tic far “Sguab às a h-uile dàta Babilim nuair a thèid a dhì-stàladh” ann an Roghainnean Babilim gach làraich, agus dì-ghnìomhaich a-rithist. A bheil thu airson a dhì-ghnìomhachadh co-dhiù?' . "\0" . 'Tha %1$d làrach air an lìonra seo air an suidheachadh gus an dearbh-aithne Babilim aca a sguabadh às nuair a thèid am plugan a sguabadh às. Chan urrainnear an cead-cleachdaidh pàighte a tha ceangailte ris na làraichean sin aiseag gu fèin-obrachail an uairsin; dh’fheumadh tu fios a chur gu taic Babilim aig %2$s. Gus na dearbh-aithnean a chumail, briog air Sguir dheth, thoir an tic far “Sguab às a h-uile dàta Babilim nuair a thèid a dhì-stàladh” ann an Roghainnean Babilim gach làraich, agus dì-ghnìomhaich a-rithist. A bheil thu airson a dhì-ghnìomhachadh co-dhiù?','This network has too many sites to check them one by one, and some of them may be set to erase their Babilim identity when the plugin is deleted. The paid license attached to such a site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identities, press Cancel, untick "Delete all Babilim data on uninstall" in each site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'Tha cus làraichean air an lìonra seo airson an sgrùdadh fa leth, agus dh’fhaodadh gu bheil cuid dhiubh air an suidheachadh gus an dearbh-aithne Babilim aca a sguabadh às nuair a thèid am plugan a sguabadh às. Chan urrainnear an cead-cleachdaidh pàighte a tha ceangailte ri làrach den leithid aiseag gu fèin-obrachail an uairsin; dh’fheumadh tu fios a chur gu taic Babilim aig %s. Gus na dearbh-aithnean a chumail, briog air Sguir dheth, thoir an tic far “Sguab às a h-uile dàta Babilim nuair a thèid a dhì-stàladh” ann an Roghainnean Babilim gach làraich, agus dì-ghnìomhaich a-rithist. A bheil thu airson a dhì-ghnìomhachadh co-dhiù?','Open Babilim settings'=>'Fosgail Roghainnean Babilim','Babilim could not verify this site, so nothing is downloaded or installed.'=>'Cha b\' urrainn do Babilim an làrach seo a dhearbhadh, mar sin cha deach dad a luchdadh a-nuas no a stàladh.','The service could not reach your site. A firewall, security plugin or host rule is probably blocking the request; please allow requests to /wp-json/babilim/v1/challenge.'=>'Cha b\' urrainn don t-seirbheis ruigsinn air an làrach agad. Tha e coltach gu bheil balla-teine, plugan tèarainteachd no riaghailt aig an òstair a\' bacadh na h-iarrtais; ceadaich iarrtasan gu /wp-json/babilim/v1/challenge.','Your site took too long to answer. Please try again later, and check that your host is not too slow or overloaded.'=>'Thug an làrach agad ro fhada gus freagairt. Feuch ris a-rithist an ceann greis, agus dèan cinnteach nach eil an t-òstair ro slaodach no ro thrang.','Your site answered, but not with what was expected. The REST API may be rewritten by another plugin, or that endpoint may be cached; please exclude /wp-json/babilim/v1/challenge from caching and rewriting.'=>'Fhreagair an làrach agad, ach chan ann leis na bha dùil. Dh\'fhaodadh gu bheil plugan eile ag ath-sgrìobhadh an REST API, no gu bheil an endpoint sin air a thasgadh; fàg /wp-json/babilim/v1/challenge a-mach à tasgadh agus ath-sgrìobhadh.','Please check that your site can be reached from the internet, then try again.'=>'Dèan cinnteach gun gabh an làrach agad ruigsinn on eadar-lìon, agus feuch ris a-rithist.','Re-verify'=>'Dearbh a-rithist','This site is over the size the service accepts in one sync, so some items were left out: %1$d components and %2$d locales.'=>'Tha an làrach seo nas motha na na ghabhas an t-seirbheis ann an aon sioncronachadh, agus mar sin chaidh cuid de nithean fhàgail a-mach: %1$d co-phàirtean agus %2$d locales.','This site is verified.'=>'Tha an làrach seo dearbhte.','Registration restarted.'=>'Chaidh an clàradh ath-thòiseachadh.','Sync complete.'=>'Tha an sioncronachadh deiseil.','Babilim is enabling and checking this site… Reload this page or wait for the scheduled check to finish.'=>'Tha Babilim ga chur an comas agus a\' sgrùdadh na làraich seo… Ath-luchdaich an duilleag seo no fuirich gus am bi an sgrùdadh clàraichte deiseil.','Babilim could not finish enabling (%1$s): %2$s'=>'Cha b\' urrainn do Babilim crìoch a chur air a chur an comas (%1$s): %2$s','A host that serves only one PHP request at a time cannot complete this step.'=>'Chan urrainn do dh\'òstair nach obraich ach aon iarrtas PHP aig an aon àm an ceum seo a choileanadh.','Babilim is enabled: this site is verified and %d component was found.'=>'Tha Babilim an comas: tha an làrach seo dearbhte agus chaidh %d phàirt a lorg.' . "\0" . 'Tha Babilim an comas: tha an làrach seo dearbhte agus chaidh %d phàirt a lorg.' . "\0" . 'Tha Babilim an comas: tha an làrach seo dearbhte agus chaidh %d pàirtean a lorg.' . "\0" . 'Tha Babilim an comas: tha an làrach seo dearbhte agus chaidh %d pàirt a lorg.','Babilim is disabled. Nothing more is sent; translations already installed keep working.'=>'Tha Babilim à comas. Chan eil dad eile ga chur; bidh na h-eadar-theangachaidhean a chaidh a stàladh mu thràth ag obair fhathast.','Supplementary translation index rebuilt.'=>'Chaidh clàr-amais eadar-theangachaidh leasachail ath-thogail.','Sweep complete: %d file deleted.'=>'Sguabadh deiseil: chaidh %d fhaidhle a sguabadh às.' . "\0" . 'Sguabadh deiseil: chaidh %d fhaidhle a sguabadh às.' . "\0" . 'Sguabadh deiseil: chaidh %d faidhlichean a sguabadh às.' . "\0" . 'Sguabadh deiseil: chaidh %d faidhle a sguabadh às.','Removed %d installed component.'=>'Chaidh %d phàirt stàlaichte a thoirt air falbh.' . "\0" . 'Chaidh %d phàirt stàlaichte a thoirt air falbh.' . "\0" . 'Chaidh %d pàirtean stàlaichte a thoirt air falbh.' . "\0" . 'Chaidh %d pàirt stàlaichte a thoirt air falbh.','Automatic installs are now off; turn them on again in the settings if you want them.'=>'Tha stàlaidhean fèin-obrachail dheth a-nis; cuir air a-rithist iad sna roghainnean ma tha thu gam miannachadh.','Babilim finds the plugins and themes on this site that have no translation for your language and installs one for each.'=>'Lorgaidh Babilim na plugain agus na h-ùrlaran air an làrach seo aig nach eil eadar-theangachadh don chànan agad agus stàlaichidh e eadar-theangachadh airson gach fear dhiubh.','Languages found on this site: %s.'=>'Cànanan a chaidh a lorg air an làrach seo: %s.','Available translations can be installed with one click, and missing ones can be requested. After that, new translations and updates are installed automatically (on the free plan, only for plugins and themes that already use a free slot).'=>'Gabhaidh eadar-theangachaidhean a tha ri fhaighinn a stàladh le aon bhriogadh, agus gabhaidh feadhainn a tha a dhìth iarraidh. Às dèidh sin, thèid eadar-theangachaidhean ùra agus ùrachaidhean a stàladh gu fèin-obrachail (air a’ phlana an-asgaidh, dìreach airson plugain agus ùrlaran a tha a’ cleachdadh slot an-asgaidh mar-thà).','The free plan covers a limited number of plugins and themes; your exact quota is shown in Settings after you enable Babilim.'=>'Tha am plana an-asgaidh a’ còmhdach àireamh chuingealaichte de phlugain agus de dh’ùrlaran; tha do cheart chuota ri fhaicinn ann an Roghainnean às dèidh dhut Babilim a chur an comas.','What is sent when you enable Babilim'=>'Dè a thèid a chur nuair a chuireas tu Babilim an comas','Enabling…'=>'Ga chur an comas…','Enable Babilim'=>'Cuir Babilim an comas','By clicking Enable, you agree to send the information listed above to Babilim.'=>'Le briogadh air Cuir an comas, tha thu ag aontachadh an fhiosrachadh gu h-àrd a chur gu Babilim.','Check again now'=>'Thoir sùil a-rithist an-dràsta','Babilim installed %d translation automatically since your last visit.'=>'Stàlaich Babilim %d eadar-theangachadh gu fèin-obrachail on turas mu dheireadh a thadhail thu.' . "\0" . 'Stàlaich Babilim %d eadar-theangachadh gu fèin-obrachail on turas mu dheireadh a thadhail thu.' . "\0" . 'Stàlaich Babilim %d eadar-theangachaidhean gu fèin-obrachail on turas mu dheireadh a thadhail thu.' . "\0" . 'Stàlaich Babilim %d eadar-theangachadh gu fèin-obrachail on turas mu dheireadh a thadhail thu.','Babilim is enabling and checking this site… (last attempt: %s)'=>'Tha Babilim ga chur an comas agus a\' sgrùdadh na làraich seo… (oidhirp mu dheireadh: %s)','Check again'=>'Thoir sùil a-rithist','No components synced yet.'=>'Cha deach co-phàirt sam bith a shioncronachadh fhathast.','%d succeeded'=>'%d air soirbheachadh' . "\0" . '%d air soirbheachadh' . "\0" . '%d air soirbheachadh' . "\0" . '%d air soirbheachadh','%d skipped'=>'%d air a leigeil seachad' . "\0" . '%d air an leigeil seachad' . "\0" . '%d air an leigeil seachad' . "\0" . '%d air an leigeil seachad','%d failed'=>'%d air fàiligeadh' . "\0" . '%d air fàiligeadh' . "\0" . '%d air fàiligeadh' . "\0" . '%d air fàiligeadh','%d not yet tried'=>'%d gun fheuchainn fhathast' . "\0" . '%d gun fheuchainn fhathast' . "\0" . '%d gun fheuchainn fhathast' . "\0" . '%d gun fheuchainn fhathast','%1$s nothing to do.'=>'%1$s chan eil dad ri dhèanamh.','%1$s %2$s.'=>'%1$s %2$s.','Bulk download:'=>'Luchdadh a-nuas mòr-chuid:','Bulk update:'=>'Ùrachadh mòr-chuid:','Bulk request:'=>'Iarrtas mòr-chuid:','per day'=>'gach latha','Wrong meaning'=>'Brìgh cheàrr','Wrong term'=>'Briathar ceàrr','Broken placeholder'=>'Ionad-glèidhidh briste','Wrong for this context'=>'Ceàrr airson a’ cho-theacsa seo','Wrong plural form'=>'Cruth iolra ceàrr','Negation reversed'=>'Chaidh an àicheadh a thionndadh bun-os-cionn','Translation does not load'=>'Chan eil an eadar-theangachadh a’ luchdadh','problem report categoryOther'=>'Eile','%1$s (%2$s): %3$s'=>'%1$s (%2$s): %3$s','Continuing…'=>'A’ leantainn…','Continue next batch (%d left)'=>'Lean air adhart leis an ath bhaidse (%d air fhàgail)','Search components'=>'Lorg co-phàirtean','These are the languages this site uses. You can change them in %s.'=>'Seo na cànanan a chleachdas an làrach seo. Faodaidh tu an atharrachadh ann an %s.','Upload this component?'=>'An luchdaich thu suas am pàirt seo?','There is no upload waiting for confirmation.'=>'Chan eil luchdadh suas a’ feitheamh airson dearbhadh.','Back'=>'Air ais','To translate this component, Babilim needs its source.'=>'Airson am pàirt seo eadar-theangachadh, tha feum aig Babilim air an tùs aige.','The entire plugin or theme directory of %1$s (version %2$s) will be uploaded to Babilim.'=>'Thèid eòlaire slàn a’ phlugain no an thema %1$s (tionndadh %2$s) a luchdadh suas gu Babilim.','If that directory contains keys, logs or customer data, they will be uploaded too. The service removes common sensitive files (configuration, environment, database dumps, logs, keys) but cannot guarantee it finds everything.'=>'Ma tha iuchraichean, logaichean no dàta teachdaiche sa phasgan sin, thèid an luchdadh suas cuideachd. Bheir an t-seirbheis air falbh faidhlichean mothachail cumanta (rèiteachadh, àrainneachd, dumpaichean stòran-dàta, logaichean, iuchraichean) ach chan urrainn dhi gealladh gun lorg i a h-uile gin.','The upload is kept until you ask Babilim to delete it.'=>'Thèid an luchdadh suas a chumail gus an iarr thu air Babilim a sguabadh às.','It is stored by the service\'s hosting provider and processed by AI models to produce the translation.'=>'Thèid a stòradh le solaraiche aoigheachd na seirbheis agus a phròiseasadh le modailean AI gus an eadar-theangachadh a dhèanamh.','The original text and the translations made from it will be provided to other sites that install the same version.'=>'Thèid an teacsa tùsail agus na h-eadar-theangachaidhean a rinneadh uaith a thoirt do làraichean eile a stàlaicheas an aon tionndadh.','By continuing you confirm that you have the right to upload this component.'=>'Ma leanas tu air adhart, dearbhaidh tu gu bheil còir agad am pàirt seo a luchdadh suas.','Upload and request'=>'Luchdaich suas is iarr','Uploading…'=>'Ag luchdadh suas…','Cancel'=>'Sguir dheth','Uploading'=>'Ag luchdadh suas','There is no upload in progress.'=>'Chan eil luchdadh suas a’ dol.','Uploading part %1$d of %2$d…'=>'Ag luchdadh suas pàirt %1$d à %2$d…','Continue'=>'Lean air adhart','Confirm'=>'Dearbh','Remove'=>'Thoir air falbh','Roll back'=>'Till air ais','Nothing to confirm.'=>'Chan eil dad ri dhearbhadh.','Choose a language'=>'Tagh cànan','Roll back and report'=>'Till air ais agus dèan aithris','Report a problem'=>'Dèan aithris air duilgheadas','Nothing to choose.'=>'Chan eil dad ri thaghadh.','%1$s: %2$s. Choose the language.'=>'%1$s: %2$s. Tagh an cànan.','Supplementary translations'=>'Eadar-theangachaidhean leasachail','Each component\'s own contribution to each locale\'s shared default-domain supplement.'=>'Cuibhreann fhèin gach pàirt do leasachadh an raoin bhunaiteach co-roinnte aig gach ionad-cànain.','Component'=>'Pàirt','Language'=>'Cànan','Included in index'=>'Air a ghabhail a-steach san chlàr-amais','Entries'=>'Inntrigidhean','Conflicting keys'=>'Iuchraichean a tha an còmhstri','Yes'=>'Tha','No — component inactive'=>'Chan eil — pàirt neo-ghnìomhach','No — installed version differs from the active one'=>'Chan eil — tha an tionndadh a chaidh a stàladh eadar-dhealaichte on tè ghnìomhach','No — component removed'=>'Chan eil — pàirt air a thoirt air falbh','No'=>'Chan eil','Only a network administrator can do this, because it changes translation files shared by every site on this network.'=>'Chan urrainn ach do rianaire lìonraidh seo a dhèanamh, oir atharraichidh e faidhlichean eadar-theangachaidh a tha air an co-roinneadh leis a h-uile làrach air an lìonra seo.','Babilim could not finish verifying this site (the service could not reach it back). Registration is paused.'=>'Cha b\' urrainn do Babilim crìoch a chur air dearbhadh na làraich seo (cha b\' urrainn dhan t-seirbheis ceangal air ais ris an làrach). Tha an clàradh air a chur air stad.','This site already has an active registration that can no longer be recovered automatically.'=>'Tha clàradh gnìomhach aig an làrach seo mu thràth nach gabh aiseag gu fèin-obrachail tuilleadh.','Restart registration'=>'Ath-thòisich an clàradh','Babilim settings'=>'Roghainnean Babilim','General'=>'Coitcheann','Advanced'=>'Adhartach','Languages'=>'Cànanan','Automatic installs'=>'Stàlaidhean fèin-obrachail','Install available translations automatically'=>'Stàlaich eadar-theangachaidhean ri fhaighinn gu fèin-obrachail','On the free plan, only components that already use one of your free slots are installed automatically, so no new slot is taken.'=>'Air a’ phlana an-asgaidh, cha tèid ach pàirtean a tha ag cleachdadh fear de na slotaichean an-asgaidh agad a stàladh gu fèin-obrachail, mar sin cha tèid slot ùr a ghabhail.','This site is part of a multisite network, which does not install new translations automatically. Translations that are already installed are still updated.'=>'Tha an làrach seo na pàirt de lìonra ioma-làraich, nach stàlaich eadar-theangachaidhean ùra gu fèin-obrachail. Thèid eadar-theangachaidhean a tha air an stàladh mu thràth ùrachadh fhathast.','Custom overrides'=>'Ath-sgrìobhaidhean gnàthaichte','Keep my own translation overrides when purging everything or uninstalling this plugin.'=>'Cùm na h-ath-sgrìobhaidhean eadar-theangachaidh agam fhìn nuair a thèid a h-uile càil a ghlanadh no am plugan seo a dhì-stàladh.','Translation files you put in %s always take priority over Babilim\'s. They are kept unless you uncheck this.'=>'Gabhaidh faidhlichean eadar-theangachaidh a chuireas tu ann an %s prìomhachas an-còmhnaidh thairis air feadhainn Babilim. Bidh iad air an cumail mura toir thu a\' chromag às a\' bhogsa seo.','Uninstall'=>'Dì-stàlaich','Delete all Babilim data on uninstall'=>'Sguab às a h-uile dàta Babilim nuair a thèid a dhì-stàladh','Off by default: deleting the plugin keeps this site\'s identity, so a reinstall can reuse it.'=>'Dheth a ghnàth: ma sguabas tu às am plugan, thèid dearbh-aithne na làraich seo a chumail, gus an gabh a h-ath-chleachdadh ma stàlaicheas tu am plugan a-rithist.','Account'=>'Cunntas','Save changes'=>'Sàbhail na h-atharraichean','Disable Babilim'=>'Cuir Babilim à comas','Installed translations are kept, but no further checks or downloads will run.'=>'Thèid na h-eadar-theangachaidhean a chaidh a stàladh a chumail, ach cha ruith sgrùdaidhean no luchdaidhean a-nuas sam bith tuilleadh.','Disable Babilim? Installed translations are kept, but no further checks or downloads will run.'=>'A bheil thu airson Babilim a chur à comas? Thèid na h-eadar-theangachaidhean a chaidh a stàladh a chumail, ach cha ruith sgrùdaidhean no luchdaidhean a-nuas sam bith tuilleadh.','This site is not registered with Babilim yet.'=>'Chan eil an làrach seo clàraichte le Babilim fhathast.','This site is already licensed. Reload the page.'=>'Tha an làrach seo fo cheadachas mu thràth. Ath-luchdaich an duilleag.','Checkout is not available for this site right now.'=>'Chan eil pròiseas a’ phàighidh ri fhaighinn airson na làraich seo an-dràsta.','Could not start checkout: %s'=>'Cha b’ urrainnear pròiseas a’ phàighidh a thòiseachadh: %s','Babilim is not enabled.'=>'Chan eil Babilim an comas.','Not registered yet'=>'Gun chlàradh fhathast','Not verified'=>'Gun dearbhadh','Verified'=>'Dearbhte','Status'=>'Staid','Licensed'=>'Fo cheadachas','Partner'=>'Com-pàirtiche','Free'=>'An-asgaidh','License'=>'Ceadachas','Upgrade this site'=>'Uasghrèadaich an làrach seo','One-time purchase for this site: %1$s %2$s. Includes all future translation updates. Payment is handled by Paddle in a new tab.'=>'Ceannachd aon-turas airson na làraich seo: %1$s %2$s. Gabhaidh e a-steach a h-uile ùrachadh eadar-theangachaidh san àm ri teachd. Bidh Paddle a’ làimhseachadh a’ phàighidh ann an taba ùr.','This issues a new restore code and the previous one stops working. Continue?'=>'Bheir seo a-mach còd aiseag ùr agus stadaidh an seann fhear ag obair. A bheil thu airson leantainn air adhart?','Show a new restore code'=>'Seall còd aiseag ùr','rc_…'=>'rc_…','Restore code'=>'Còd aiseag','Restore purchase'=>'Aisig ceannach','Bought a license for this domain before? Enter the restore code you received at checkout.'=>'An do cheannaich thu ceadachas airson an àrainn seo roimhe? Cuir a-steach an còd aiseag a fhuair thu nuair a rinn thu am pàigheadh.','That does not look like a restore code.'=>'Chan eil sin coltach ri còd aiseag.','This restore code was not recognised for this site.'=>'Cha deach an còd aiseag seo aithneachadh airson na làraich seo.','Too many attempts. Try again tomorrow.'=>'Cus oidhirpean. Feuch ris a-rithist a-màireach.','This site must be verified first.'=>'Feumaidh an làrach seo a bhith dearbhte an toiseach.','Could not restore the purchase: %s'=>'Cha b’ urrainn dhuinn a’ cheannachd aiseag: %s','Purchase restored. This site is now licensed.'=>'Chaidh a’ cheannachd aiseag. Tha cead aig an làrach seo a-nis.','This site has no purchase to show a code for.'=>'Chan eil ceannachd aig an làrach seo airson còd a shealltainn.','Could not show a new restore code: %s'=>'Cha b’ urrainn dhuinn còd aiseag ùr a shealltainn: %s','Your new restore code: %s. Keep it somewhere safe — the previous code no longer works.'=>'An còd aiseag ùr agad: %s. Cùm an àiteigin sàbhailte e – chan obraich an seann chòd tuilleadh.','What is sent when Babilim checks this site'=>'Na thèid a chur nuair a sgrùdas Babilim an làrach seo','(detected)'=>'(air a lorg)','No language is managed yet.'=>'Chan eil cànan sam bith fo stiùireadh fhathast.','Babilim adds translations for every language checked here.'=>'Cuiridh Babilim eadar-theangachaidhean ris airson gach cànan a tha air a thaghadh an seo.','Add another language'=>'Cuir cànan eile ris','Choose a language…'=>'Tagh cànan…','Could not load the full WordPress.org locale list from the service, so no other language can be added right now.'=>'Cha b’ urrainn dhuinn liosta slàn nan ionadan-cànain WordPress.org a luchdadh on t-seirbheis, agus mar sin chan urrainn cànan eile a chur ris an-dràsta.','Theme'=>'Ùrlar','Plugin'=>'Plugan','Free quota'=>'Cuota an-asgaidh','Downloads: %1$d/%2$d (%3$s)'=>'Luchdaidhean a-nuas: %1$d/%2$d (%3$s)','Supplementary translation index'=>'Clàr-amais nan eadar-theangachaidhean leasachail','Built'=>'Air a thogail','Included'=>'Air a ghabhail a-steach','Excluded'=>'Air fhàgail a-mach','Already in WordPress core'=>'Cheana ann am bunait WordPress','Supplementary translation maintenance'=>'Cumail suas an eadar-theangachaidh a bharrachd','Maintenance status is not available right now.'=>'Chan eil staid a’ chumail suas ri fhaighinn an-dràsta.','A cleanup was paused on %1$s: %2$s. Nothing was deleted.'=>'Chaidh glanadh a chuir na stad air %1$s: %2$s. Cha deach dad a sguabadh às.','Last cleanup on %1$s: %2$d newly marked, %3$d file(s) deleted, %4$d record(s) removed.'=>'An glanadh mu dheireadh air %1$s: %2$d air a chomharrachadh às ùr, %3$d faidhle air an sguabadh às, %4$d clàr air a thoirt air falbh.','No cleanup has run yet.'=>'Cha deach glanadh a ruith fhathast.','A translation-index write conflicted with another request on %1$s (%2$s) and was not applied; the most recent version was kept.'=>'Bha sgrìobhadh clàr-amais eadar-theangachaidh ann an còmhstri le iarrtas eile aig %1$s (%2$s) agus cha deach a chur an sàs; chaidh an tionndadh as ùire a chumail.','A translation-index write on %1$s (%2$s) could not be completed and was not applied (%3$s).'=>'Cha b’ urrainn dhuinn sgrìobhadh clàr-amais eadar-theangachaidh aig %1$s (%2$s) a choileanadh agus cha deach a chur an sàs (%3$s).','Maintenance'=>'Cumail-suas','Rebuild index now'=>'Ath-thog an clàr-amais a-nis','Sweep now'=>'Sguab an-dràsta','Danger zone'=>'Raon cunnartach','Removes every language file Babilim has installed for every plugin and theme on this site.'=>'Bheir seo air falbh a h-uile faidhle cànain a stàlaich Babilim airson gach plugan agus ùrlar air an làrach seo.','Remove everything Babilim installed? This deletes every language file it installed for every plugin and theme on this site.'=>'A bheil thu airson a h-uile dad a stàlaich Babilim a thoirt air falbh? Sguabaidh seo às a h-uile faidhle cànain a stàlaich e airson gach plugan agus ùrlar air an làrach seo.','Remove everything Babilim installed'=>'Thoir air falbh a h-uile dad a stàlaich Babilim','This string is too long to be sent as a report, so no report form is offered for it.'=>'Tha an sreang seo ro fhada airson a chur mar aithisg, mar sin chan eil foirm aithisge ga tabhann dhi.','Category'=>'Roinn-seòrsa','Choose a category…'=>'Tagh roinn-seòrsa…','Roll back and send report'=>'Till air ais agus cuir aithris','Send report'=>'Cuir aithisg','Some of this component\'s text is hard-coded by its author and can\'t be translated by a language pack.'=>'Tha cuid de theacsa a’ phàirt seo air a chòdachadh gu cruaidh leis an ùghdar agus chan urrainn do phacaid cànain eadar-theangachadh.','WordPress.org'=>'WordPress.org','Bundled with the theme'=>'An cois an ùrlair','Bundled with the plugin'=>'An cois a’ phlugain','Upload was not accepted'=>'Cha deach an luchdadh suas a ghabhail ris','Upload expired before it finished'=>'Dh’fhalbh an ùine air an luchdadh suas mus do chrìochnaich e','No translation'=>'Gun eadar-theangachadh','Upload in progress — continue or cancel'=>'Luchdadh suas a’ dol – lean air adhart no sguir dheth','Scheduled, waiting to be processed'=>'Clàraichte, a’ feitheamh ri pròiseasadh','Translating…'=>'Ag eadar-theangachadh…','Translation failed'=>'Dh’fhàillig an t-eadar-theangachadh','Free quota used'=>'Cuota an-asgaidh air a chleachdadh','Needs a paid license'=>'Feumaidh e cead-cleachdaidh pàighte','Not supported'=>'Gun taic','Status unknown'=>'Staid neo-aithnichte','translation statusInstalled'=>'Stàlaichte','Update available'=>'Ùrachadh ri fhaighinn','Removed after a failed integrity check'=>'Chaidh a thoirt air falbh às dèidh sgrùdadh slàine a dh’fhàillig','Installed · built for %s, new version scheduled'=>'Stàlaichte · air a thogail airson %s, tionndadh ùr clàraichte','Installed · built for a different version, new version scheduled'=>'Stàlaichte · air a thogail airson tionndadh eile, tionndadh ùr clàraichte','Installed · built for %s, translating the new version…'=>'Stàlaichte · air a thogail airson %s, ag eadar-theangachadh an tionndaidh ùir…','Installed · built for a different version, translating the new version…'=>'Stàlaichte · air a thogail airson tionndadh eile, ag eadar-theangachadh an tionndaidh ùir…','Installed · built for %1$s, this site has %2$s'=>'Stàlaichte · air a thogail airson %1$s, tha %2$s aig an làrach seo','Installed · built for %s'=>'Stàlaichte · air a thogail airson %s','Installed · built for a different version'=>'Stàlaichte · air a thogail airson tionndadh eile','Installed · built for %s, new version failed'=>'Air a stàladh · air a thogail airson %s, dh\'fhàillig an tionndadh ùr','Installed · built for a different version, new version failed'=>'Air a stàladh · air a thogail airson tionndadh eile, dh\'fhàillig an tionndadh ùr','Installed · built for %s, new version needs a paid license'=>'Air a stàladh · air a thogail airson %s, feumaidh an tionndadh ùr cead-cleachdaidh pàighte','Installed · built for a different version, new version needs a paid license'=>'Air a stàladh · air a thogail airson tionndadh eile, feumaidh an tionndadh ùr cead-cleachdaidh pàighte','Installed · built for %s, free quota used'=>'Air a stàladh · air a thogail airson %s, cuota an-asgaidh air a chleachdadh','Installed · built for a different version, free quota used'=>'Air a stàladh · air a thogail airson tionndadh eile, cuota an-asgaidh air a chleachdadh','translation statusAvailable'=>'Ri fhaighinn','Installed · %s'=>'Air a stàladh · %s','Available · %s'=>'Ri fhaighinn · %s','Update'=>'Ùraich','Download'=>'Luchdaich a-nuas','Updating…'=>'Ag ùrachadh…','Downloading…'=>'A’ luchdadh a-nuas…','Retry request'=>'Feuch an iarrtas a-rithist','Request newer translation'=>'Iarr eadar-theangachadh nas ùire','Request translation'=>'Iarr eadar-theangachadh','Requesting…'=>'Ag iarraidh…','Requesting a translation uses one of your free slots, unless this component already uses one. A failed translation does not give the slot back.'=>'Ma dh\'iarras tu eadar-theangachadh, cleachdaidh e aon de na slotaichean an-asgaidh agad, ach ma tha am pàirt seo a\' cleachdadh fear mu thràth. Chan eil eadar-theangachadh a dh\'fhàillig a\' toirt an t-slot air ais.','If this component does not use one of your free slots yet, requesting a translation uses one. A failed translation does not give the slot back. Continue?'=>'Mura h-eil am pàirt seo a\' cleachdadh aon de na slotaichean an-asgaidh agad fhathast, cleachdaidh iarrtas eadar-theangachaidh fear. Chan eil eadar-theangachadh a dh\'fhàillig a\' toirt an t-slot air ais. A bheil thu airson leantainn air adhart?','No plugins or themes found.'=>'Cha deach plugain no ùrlaran a lorg.','Clear filters'=>'Falamhaich na criathragan','No components match these filters. %s'=>'Chan eil co-phàirt sam bith a’ freagairt ris na criathragan seo. %s','Select all'=>'Tagh na h-uile','All'=>'Na h-uile','Available'=>'Ri fhaighinn','Updates'=>'Ùrachaidhean','Requestable'=>'Ri iarraidh','Installed'=>'Air a stàladh','Plugins'=>'Plugain','Themes'=>'Ùrlaran','All languages'=>'Gach cànan','%d to install'=>'%d ri stàladh' . "\0" . '%d ri stàladh' . "\0" . '%d ri stàladh' . "\0" . '%d ri stàladh','Language:'=>'Cànan:','Bulk actions apply to every matching language of each selected component.'=>'Bidh mòr-ghnìomhan a\' buntainn ris a h-uile cànan a fhreagras air na criathragan airson gach pàirt a chaidh a thaghadh.','Bulk actions apply only to the selected language of each selected component.'=>'Bidh mòr-ghnìomhan a\' buntainn ris a\' chànan a chaidh a thaghadh a-mhàin airson gach pàirt a chaidh a thaghadh.','Version %s'=>'Tionndadh %s','Theme · %s'=>'Ùrlar · %s','Plugin · %s'=>'Plugan · %s','Remove the %2$s translation of %1$s from this site?'=>'A bheil thu airson an t-eadar-theangachadh %2$s de %1$s a thoirt air falbh on làrach seo?','Roll back the %2$s translation of %1$s to the previous build?'=>'A bheil thu airson eadar-theangachadh %2$s de %1$s a thilleadh dhan build roimhe?','%1$s: %2$s'=>'%1$s: %2$s','%1$s: %2$s (%3$s)'=>'%1$s: %2$s (%3$s)','The registration challenge is not in the expected form.'=>'Chan eil an dùbhlan clàraidh san riochd ris a bheil dùil.','That is not a valid build identifier.'=>'Chan e aithnichear build dligheach a tha sin.','Refusing to write outside the Babilim language-file directory.'=>'A\' diùltadh sgrìobhadh taobh a-muigh pasgan faidhlichean cànain Babilim.','Could not write the downloaded package to disk.'=>'Cha b\' urrainn dhuinn am pacaid a chaidh a luchdadh a-nuas a sgrìobhadh dhan diosg.','Unexpected HTTP %d response.'=>'Freagairt HTTP %d ris nach robh dùil.','This site\'s URL, so the service can verify you own it.'=>'URL na làraich seo, gus an urrainn don t-seirbheis dearbhadh gur leatsa i.','Your WordPress version, to serve compatible translation files.'=>'Tionndadh WordPress agad, gus faidhlichean eadar-theangachaidh co-chòrdail a thoirt seachad.','Your PHP version, for compatibility.'=>'Tionndadh PHP agad, airson co-chòrdalachd.','This plugin\'s own version, so the service can tell you to update it if it\'s too old to talk to.'=>'Tionndadh a\' phlugain seo fhèin, gus an urrainn don t-seirbheis innse dhut a ùrachadh ma tha e ro shean airson conaltradh ris.','This site\'s configured locale.'=>'Locale rèiteichte na làraich seo.','Every locale in use on this site (site locale, installed language packs, user locales, and any you add manually). No locale is treated differently from another.'=>'A h-uile locale a tha ga chleachdadh air an làrach seo (locale na làraich, pacaidean cànain stàlaichte, locales chleachdaichean, agus na chuireas tu ris le làimh). Chan eil locale sam bith air a làimhseachadh ann an dòigh eadar-dhealaichte o gin sam bith eile.','(a public key generated for this site)'=>'(iuchair phoblach a chaidh a ghineadh airson na làraich seo)','This site\'s install public key, used to prove requests genuinely come from this site. Only the public half is ever sent.'=>'Iuchair phoblach stàlaichte na làraich seo, a thathas a\' cleachdadh gus dearbhadh gu bheil iarrtasan a\' tighinn bhon làrach seo da-rìribh. Cha tèid ach an leth poblach a chur a-chaoidh.','Every installed plugin/theme: its slug, version, text domain(s), whether it\'s a wp.org listing, its own bundled locales, and which locales you\'ve already installed a Babilim translation for.'=>'A h-uile plugain/cuspair a chaidh a stàladh: an slug, an tionndadh, raon(an) an teacsa, an e liostadh wp.org a th\' ann, na cànanan aige fhèin a tha ann am pasgan, agus dè na cànanan dhan do stàlaich thu eadar-theangachadh Babilim mu thràth.','Only when you confirm an upload for a plugin or theme that is not on WordPress.org: that component\'s entire directory, as a zip.'=>'Dìreach nuair a dhearbhas tu luchdadh suas airson plugain no cuspair nach eil air WordPress.org: pasgan slàn a\' phàirt sin, mar zip.','(generic codes and coordinates only)'=>'(còdan coitcheann agus co-chomharran a-mhàin)','Up to 20 pending diagnostic events (e.g. a file that failed its integrity check), each just a code, component, and locale, and never any string content or translated text.'=>'Suas gu 20 tachartas breithneachaidh a tha ri feitheamh (m.e. faidhle nach do chaidh leis an sgrùdadh slàine), gach fear dhiubh dìreach còd, pàirt agus cànan, agus gun susbaint sreang no teacsa eadar-theangaichte idir.','Unsafe locale: %s'=>'Locale neo-shàbhailte: %s','Manifest unavailable: %s'=>'Chan eil manifest ri fhaighinn: %s','Could not determine active components; the existing merged index was left unchanged.'=>'Cha b\' urrainn dhuinn na pàirtean gnìomhach a dhearbhadh; cha deach an clàr-amais aonaichte a th\' ann a atharrachadh.','Could not determine installed plugins/themes; sweep skipped, nothing was deleted.'=>'Cha b\' urrainn dhuinn faighinn a-mach dè na plugain/cuspairean a chaidh a stàladh; chaidh an sguabadh a leum thairis agus cha deach dad a sguabadh às.','Sweep aborted without orphaning anything: %s.'=>'Chaidh an sguabadh a chuir dheth gun dìlleachdan a dhèanamh de dad: %s.','The cleanup ran, but some of its changes could not be recorded in the translation index; the next cleanup will retry them.'=>'Ruith an glanadh, ach cha b\' urrainn dhuinn cuid de na h-atharrachaidhean aige a chlàradh sa chlàr-amais eadar-theangachaidh; feuchaidh an ath ghlanadh ris an clàradh a-rithist.','component kind in the sweep brake messagetheme'=>'cuspair','component kind in the sweep brake messageplugin'=>'plugan','it would orphan every managed %1$s component (%2$d of %2$d)'=>'dhèanadh e dìlleachdan de gach pàirt fo stiùir de sheòrsa %1$s (%2$d à %2$d)','it would orphan %1$d of %2$d managed components (more than half)'=>'dhèanadh e dìlleachdan de %1$d à %2$d de phàirtean fo stiùir (barrachd air leth)','The merged index for \'%s\' was rebuilt, but the translation index could not record it; the next rebuild will retry.'=>'Chaidh an clàr-amais aonaichte airson \'%s\' ath-thogail, ach cha b\' urrainn don chlàr-amais eadar-theangachaidh a chlàradh; feuchaidh an ath-thogail a leanas a-rithist.','Could not write the staged merged index.'=>'Cha b\' urrainn dhuinn an clàr-amais aonaichte air a ullachadh a sgrìobhadh.','Re-parsed entry count did not match the built index.'=>'Cha robh an àireamh de chlàran a chaidh ath-pharsadh co-ionnan ris a\' chlàr-amais a chaidh a thogail.','Could not move the merged index for \'%s\' into place; the previous served index (if any) was removed rather than left half-updated. No default-domain supplement is served for this locale until the next successful rebuild.'=>'Cha b\' urrainn dhuinn an clàr-amais aonaichte airson \'%s\' a chur na àite; chaidh an clàr-amais roimhe a bha ga sheirbheiseadh (ma bha gin ann) a thoirt air falbh seach a fhàgail letheach ùraichte. Cha tèid leasachadh an raoin bhunaiteach a sheirbheiseadh airson an locale seo gus an ath-thogail shoirbheachail a leanas.','Could not open zip: %s'=>'Cha b\' urrainn dhuinn an zip fhosgladh: %s','Zip has no manifest.json.'=>'Chan eil manifest.json anns an zip.','manifest.json in the zip is not valid JSON.'=>'Chan eil manifest.json san zip na JSON dligheach.','manifest.json\'s \'%s\' does not match the expected value.'=>'Chan eil \'%s\' aig manifest.json a\' maidseadh an luach a bha dùil.','Another installation is running; try again in a moment.'=>'Tha stàladh eile a\' ruith; feuch a-rithist an ceann tamaill.','Not a valid server_build_id: %s'=>'Chan e server_build_id dligheach a th\' ann: %s','The package manifest\'s kind \'%1$s\' does not match the requested kind \'%2$s\'.'=>'Chan eil seòrsa manifest a\' phacaid \'%1$s\' a\' maidseadh an t-seòrsa a chaidh iarraidh \'%2$s\'.','The package\'s text domain \'%1$s\' does not match this site\'s copy of the component (\'%2$s\'), so it was not installed.'=>'Chan eil raon an teacsa aig a\' phacaid \'%1$s\' a\' maidseadh lethbhreac na làraich seo dhen phàirt (\'%2$s\'), agus mar sin cha deach a stàladh.','The given domain \'%1$s\' matches neither the package manifest\'s own slug \'%2$s\' nor its text_domain \'%3$s\'.'=>'Chan eil an raon a chaidh a thoirt \'%1$s\' a\' maidseadh slug manifest a\' phacaid fhèin \'%2$s\' no an text_domain aige \'%3$s\'.','Unsafe slug: %s'=>'Slug neo-shàbhailte: %s','Unsafe text_domain: %s'=>'text_domain neo-shàbhailte: %s','The package has no %s for its own text domain.'=>'Chan eil %s anns a\' phacaid airson raon an teacsa aice fhèin.','manifest.json is missing or has an invalid \'%s\'.'=>'Tha manifest.json a dhìth no tha \'%s\' mì-dhligheach ann.','manifest.json is missing or has an invalid \'entries\'.'=>'Tha manifest.json a dhìth no tha \'entries\' mì-dhligheach ann.','manifest.json is missing or has an invalid \'files\'.'=>'Tha manifest.json a dhìth no tha \'files\' mì-dhligheach ann.','manifest.json is missing or has an invalid \'extra_domains\'.'=>'Tha manifest.json a dhìth no tha \'extra_domains\' mì-dhligheach ann.','manifest.json is missing or has an invalid \'build_no\'.'=>'Tha manifest.json a dhìth no tha \'build_no\' mì-dhligheach ann.','manifest.json\'s \'server_build_id\' is not a valid build id.'=>'Chan e id togail dhligheach a th’ ann an \'server_build_id\' aig manifest.json.','manifest.json\'s \'contract\' is not a valid version string.'=>'Chan e sreang tionndaidh dhligheach a th’ ann an “contract” aig manifest.json.','manifest.json\'s \'status\' must be \'published\'.'=>'Feumaidh “status” ann am manifest.json a bhith “published”.','manifest.json\'s \'kind\' must be \'plugin\' or \'theme\'.'=>'Feumaidh \'kind\' ann am manifest.json a bhith \'plugin\' no \'theme\'.','manifest.json has an invalid \'default_domain_entries\'.'=>'Tha \'default_domain_entries\' mì-dhligheach ann am manifest.json.','manifest.json has an invalid \'default_domain_files\'.'=>'Tha \'default_domain_files\' mì-dhligheach ann am manifest.json.','expected_manifest is missing or has an invalid \'%s\'.'=>'Tha expected_manifest a dhìth no tha \'%s\' mì-dhligheach ann.','expected_manifest\'s \'server_build_id\' is not a valid build id.'=>'Chan e id togail dhligheach a th’ ann an “server_build_id” aig expected_manifest.','No record for %s'=>'Chan eil clàr ann airson %s','One or more served files no longer match the manifest.'=>'Chan eil faidhle no dhà no barrachd a chaidh a lìbhrigeadh a’ freagairt ris an manifest tuilleadh.','No previous build to roll back to.'=>'Chan eil togail roimhe ann airson tilleadh air ais thuice.','The change could not be recorded in the translation index; please try again.'=>'Cha b’ urrainn dhuinn an t-atharrachadh a chlàradh sa chlàr-amais eadar-theangachaidh; feuch a-rithist e.','Unknown kind: %s'=>'Seòrsa neo-aithnichte: %s','Unsafe domain: %s'=>'Raon neo-thèarainte: %s','The text domain \'%1$s\' (%2$s) is already served for another installed component (%3$s); nothing was installed.'=>'Tha an raon-teacsa \'%1$s\' (%2$s) \'ga sheirbheiseadh mu thràth airson pàirt stàlaichte eile (%3$s); cha deach dad a stàlaichadh.','Rolling back would overwrite \'%1$s\' (%2$s), which is now served for another installed component (%3$s); nothing was changed.'=>'Bhiodh tilleadh air ais a’ sgrìobhadh thairis air \'%1$s\' (%2$s), a tha a-nis air a sheirbheiseadh airson pàirt stàlaichte eile (%3$s); cha deach dad atharrachadh.','Zip is missing expected file: %s'=>'Tha faidhle ris an robh dùil a dhìth sa zip: %s','sha256 mismatch for %s'=>'mì-fhreagarrachd sha256 airson %s','The package declares no main translation file.'=>'Chan eil a’ phacaid a’ cur an cèill prìomh fhaidhle eadar-theangachaidh.','Zip is missing expected default file: %s'=>'Tha am faidhle bun-roghainn ris an robh dùil a dhìth sa zip: %s','sha256 mismatch for default/%s'=>'mì-fhreagarrachd sha256 airson default/%s','Could not stage %s'=>'Cha b’ urrainn dhuinn %s a ullachadh','Could not stage default/%s'=>'Cha b’ urrainn dhuinn default/%s a ullachadh','Entry count mismatch for %s'=>'Chan eil an àireamh de dh’inntrigidhean a’ maidseadh airson %s','Could not verify entry count for %s'=>'Cha b’ urrainn dhuinn an àireamh de dh’inntrigidhean a dhearbhadh airson %s','l10n.php entry count mismatch for %s'=>'Chan eil an àireamh de dh’inntrigidhean l10n.php a’ maidseadh airson %s','Default supplement entry count mismatch.'=>'Chan eil an àireamh de dh’inntrigidhean a’ phàirt-leasachaidh bun-roghainn a’ maidseadh.','The package produced no servable main translation file.'=>'Cha tug a’ phacaid prìomh fhaidhle eadar-theangachaidh a ghabhas a sheirbheiseadh gu buil.','Could not prepare %s for rollback.'=>'Cha b’ urrainn dhuinn %s a ullachadh airson tilleadh air ais.','Could not back up %s before replacing it.'=>'Cha b’ urrainn dhuinn lethbhreac-glèidhidh de %s a dhèanamh mus deach a chur na àite.','Could not move %s into place.'=>'Cha b’ urrainn dhuinn %s a ghluasad dhan àite aige.','Could not read %s back after moving it into place.'=>'Cha b’urrainn dhuinn %s a leughadh air ais às dèidh dha a bhith air a ghluasad dhan àite aige.','English (United States)'=>'Beurla (na Stàitean Aonaichte)','Babilim_Manifest is unavailable: %s'=>'Chan eil Babilim_Manifest ri fhaighinn: %s','could not read _manifest.json: %s'=>'cha b’ urrainn dhuinn _manifest.json a leughadh: %s','failed to parse _manifest.json: %s'=>'Cha b’ urrainnear _manifest.json a pharsadh: %s','_manifest.json has an unexpected structure'=>'Tha structar air _manifest.json nach robh dùil ris','Could not create the package archive.'=>'Cha b’ urrainnear tasglann a’ phacaid a chruthachadh.','No writable temporary directory is available for packaging.'=>'Chan eil pasgan sealach so-sgrìobhte ri fhaighinn airson pacaigeadh.','A file in the component could not be read, so it was not packaged.'=>'Cha deach faidhle sa phàirt a phacaigeadh oir cha robh e comasach a leughadh.','Only plugins and themes can be packaged.'=>'Chan urrainnear ach plugain agus cuspairean a phacaigeadh.','The component\'s main file was not found.'=>'Cha deach prìomh fhaidhle a’ phàirt a lorg.','The component is not inside the plugins or themes directory.'=>'Chan eil am pàirt am broinn an eòlaire phlugain no ùrlaran.','Babilim ran out of time for this step and will continue on the next check.'=>'Dh’fhalbh an ùine aig Babilim airson a’ cheum seo agus leanaidh e air aig an ath-sgrùdadh.','Babilim could not verify this site, so nothing is downloaded or installed until verification succeeds.'=>'Cha b’ urrainn do Babilim an làrach seo a dhearbhadh, agus mar sin cha tèid dad a luchdadh a-nuas no a stàladh gus an soirbhich leis an dearbhadh.','Registration response was missing required fields.'=>'Bha raointean riatanach a dhìth air freagairt a’ chlàraidh.','No pending challenge to verify.'=>'Chan eil dùbhlan ri dhearbhadh an-dràsta.','Verify response was missing site_token.'=>'Bha site_token a dhìth air freagairt an dearbhaidh.','No site id is on file to rotate a token for.'=>'Chan eil ID làraich clàraichte gus tòcan na làraich ùrachadh.','Rotate-token response was missing site_token.'=>'Bha site_token a dhìth air freagairt an iarrtais gus an tòcan ùrachadh.','nonce must be a hexadecimal string.'=>'Feumaidh an nonce a bhith na shreang heicseadheicimeach.','No pending challenge for this nonce.'=>'Chan eil dùbhlan sam bith ri feitheamh airson an nonce seo.','Too many requests.'=>'Cus iarrtasan.','The service asked this site to wait before syncing again.'=>'Dh’iarr an t-seirbheis air an làrach seo feitheamh mus sioncronaich i a-rithist.','This site has %1$d components across %2$d languages, which needs %3$d check batches; Babilim can handle at most %4$d per run. Reduce the managed languages in Settings or deactivate unused plugins and themes, then press Check again now.'=>'Tha %1$d pàirt aig an làrach seo thar %2$d cànan, agus tha feum air %3$d baidse sgrùdaidh; chan urrainn do Babilim barrachd air %4$d a làimhseachadh anns gach ruith. Lùghdaich na cànanan a thathar a’ riaghladh ann an Roghainnean no cuir à comas na plugain agus na h-ùrlaran nach eil gan cleachdadh, agus an uair sin briog air Thoir sùil a-rithist an-dràsta.','Babilim could not finish checking this site.'=>'Cha b’ urrainn do Babilim crìoch a chur air sgrùdadh na làraich seo.','This site\'s address is too long for Babilim to register.'=>'Tha seòladh na làraich seo ro fhada airson Babilim a chlàradh.','This site\'s locale code is not one Babilim can register.'=>'Chan urrainn do Babilim còd ionadail na làraich seo a chlàradh.','The download response was missing a usable location.'=>'Cha robh ionad so-chleachdte ann am freagairt an luchdaidh a-nuas.','The service\'s upload offer was incomplete.'=>'Cha robh tairgse luchdaidh suas na seirbheise coileanta.','This component is larger than the service accepts, so it cannot be uploaded.'=>'Tha am pàirt seo nas motha na na gabhas an t-seirbheis ris, agus mar sin chan urrainn dhuinn a luchdadh suas.','The packaged component could not be read.'=>'Cha b’ urrainn dhuinn am pàirt pacaichte a leughadh.','A part of the upload kept failing, so the upload was cancelled.'=>'Lean pàirt dhen luchdadh suas ag fàilligeadh, agus mar sin chaidh an luchdadh suas a chur dheth.','Could not read: %s'=>'Cha b’ urrainnear a leughadh: %s']];